const fs=require('fs'),p=require('path'),crypto=require('crypto'),asar=require('@electron/asar'),cp=require('child_process');
const root=p.resolve('tmp/electron-dist/mac-arm64/SAR Tracker Electron Validation.app');
const res=p.join(root,'Contents/Resources'),af=p.join(res,'app.asar');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const records=[];
function walk(dir,base){for(const d of fs.readdirSync(dir,{withFileTypes:true})){const f=p.join(dir,d.name),name=p.relative(base,f);if(d.isSymbolicLink()){records.push({boundary:'bundle',path:name,symlink:fs.readlinkSync(f)});continue;}if(d.isDirectory())walk(f,base);else records.push({boundary:'bundle',path:name,size:fs.statSync(f).size,sha256:hash(fs.readFileSync(f))});}}
walk(root,root);
const packages=[],suspects=[];
for(const raw of asar.listPackage(af)){const name=raw.replace(/^\//,''),st=asar.statFile(af,name);if(st.files)continue;if(st.link){records.push({boundary:'asar',path:name,symlink:st.link});continue;}const bytes=asar.extractFile(af,name);records.push({boundary:'asar',path:name,size:bytes.length,sha256:hash(bytes),unpacked:!!st.unpacked});if(/(?:^|\/)node_modules\/(?:@[^/]+\/)?[^/]+\/package.json$/.test(name)){const q=JSON.parse(bytes);packages.push({name:q.name,version:q.version,path:name});}if(bytes.subarray(0,16).toString()==='SQLite format 3\0'||bytes.subarray(0,4).equals(Buffer.from([0x50,0x4b,3,4]))||/\.(?:sararch|sararchive|zip|sqlite|sqlite3|db|mbtiles|pem|p12|key)$/i.test(name)||/(^|\/)(?:test-results|verification|scratch|profiles?|diagnostics|fixtures|\.git|\.env)(\/|$)/i.test(name))suspects.push(name);}
records.sort((a,b)=>(a.boundary+'/'+a.path).localeCompare(b.boundary+'/'+b.path));packages.sort((a,b)=>a.name.localeCompare(b.name));
fs.writeFileSync('tmp/war04b-refresh/package-manifest.json',JSON.stringify(records,null,2)+'\n');
const summary={schema:'war04b-package-inventory-v1',source:'3cdf555de93459c83198121b31053ff1d53db74e',platform:process.platform,architecture:process.arch,appAsar:{size:fs.statSync(af).size,sha256:hash(fs.readFileSync(af))},manifest:{entries:records.length,sha256:hash(fs.readFileSync('tmp/war04b-refresh/package-manifest.json'))},asarFiles:records.filter(x=>x.boundary==='asar').length,unpackedFiles:records.filter(x=>x.boundary==='bundle'&&x.path.includes('app.asar.unpacked/')),nativeModules:records.filter(x=>x.path.endsWith('.node')),extraResources:records.filter(x=>x.boundary==='bundle'&&x.path.startsWith('Contents/Resources/')&&!x.path.includes('app.asar')),packages,suspects};
fs.writeFileSync('tmp/war04b-refresh/package-summary.json',JSON.stringify(summary,null,2)+'\n');console.log(JSON.stringify({entries:records.length,asarFiles:summary.asarFiles,packages:packages.length,suspects,nativeModules:summary.nativeModules,extraResourceCount:summary.extraResources.length}));

