const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),asar=require('@electron/asar');
const root=path.resolve(process.argv[2]);
const archive=path.join(root,'resources/app.asar');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const files=[],packages=[],suspects=[];
const riskyName=/(\.(?:sararch|sararchive|zip|sqlite|sqlite3|db|mbtiles|pmtiles|p12|pfx|pem|key)$)|((?:^|\/)(?:test-results|verification|scratch|profiles?|diagnostics|fixtures|\.git|\.env|id_rsa)(?:\/|$))/i;
function inspect(boundary,name,bytes){
 files.push({boundary,path:name,size:bytes.length,sha256:hash(bytes)});
 if(riskyName.test(name)||bytes.subarray(0,16).toString()==='SQLite format 3\0'||bytes.subarray(0,8).toString()==='SARARCH2'||bytes.subarray(0,4).equals(Buffer.from([0x50,0x4b,3,4])))suspects.push({boundary,path:name});
}
function walk(dir){for(const entry of fs.readdirSync(dir,{withFileTypes:true})){
 const p=path.join(dir,entry.name),name=path.relative(root,p);
 if(entry.isSymbolicLink())files.push({boundary:'bundle',path:name,symlink:fs.readlinkSync(p)});
 else if(entry.isDirectory())walk(p);
 else inspect('bundle',name,fs.readFileSync(p));
}}
walk(root);
for(const raw of asar.listPackage(archive)){
 const name=raw.replace(/^\//,''),s=asar.statFile(archive,name);
 if(s.files)continue;
 if(s.link){files.push({boundary:'asar',path:name,symlink:s.link});continue;}
 const bytes=asar.extractFile(archive,name);inspect('asar',name,bytes);
 if(/(?:^|\/)node_modules\/(?:@[^/]+\/)?[^/]+\/package.json$/.test(name)){
  const p=JSON.parse(bytes);packages.push({name:p.name,version:p.version,path:name});
 }
}
files.sort((a,b)=>(a.boundary+'/'+a.path).localeCompare(b.boundary+'/'+b.path));
packages.sort((a,b)=>a.path.localeCompare(b.path));
fs.writeFileSync('tmp/war04b-refresh/linux-manifest.json',JSON.stringify(files,null,2)+'\n');
const r={source:'3cdf555de93459c83198121b31053ff1d53db74e',platform:'linux',architecture:'x64',appAsar:{size:fs.statSync(archive).size,sha256:hash(fs.readFileSync(archive))},entries:files.length,asarFiles:files.filter(x=>x.boundary==='asar').length,manifestSha256:hash(fs.readFileSync('tmp/war04b-refresh/linux-manifest.json')),nativeModules:files.filter(x=>x.path.endsWith('.node')),unpackedFiles:files.filter(x=>x.boundary==='bundle'&&x.path.startsWith('resources/app.asar.unpacked/')),extraResources:files.filter(x=>x.boundary==='bundle'&&x.path.startsWith('resources/')&&!x.path.includes('app.asar')),packages,suspects};
fs.writeFileSync('tmp/war04b-refresh/linux-package-summary.json',JSON.stringify(r,null,2)+'\n');
console.log(JSON.stringify({entries:r.entries,asarFiles:r.asarFiles,packages:packages.length,suspects,appAsar:r.appAsar}));
